import{_ as r,C as o,o as a,c as i,j as e,a as n,E as s,a6 as l}from"./chunks/framework.CnPv4DE1.js";const _=JSON.parse('{"title":"意义危机（如何做一件真正重要的事）","description":"","frontmatter":{"title":"意义危机（如何做一件真正重要的事）","originalTitle":"The Meaning Crisis (How To Do Something That Matters)","date":"2024-11-09","originalUrl":"https://thedankoe.com/letters/the-meaning-crisis-how-to-do-something-that-matters/","minutes":21,"sourceHash":"f9d1e17cb788320b503d7c7f6f5e999e3c56162efd1e95e3bb16ca5f20bde9cc","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-meaning-crisis-how-to-do-something-that-matters/"}]]},"headers":[],"relativePath":"letters/the-meaning-crisis-how-to-do-something-that-matters.md","filePath":"letters/the-meaning-crisis-how-to-do-something-that-matters.md"}'),h={name:"letters/the-meaning-crisis-how-to-do-something-that-matters.md"};function m(g,p,c,d,u,b){const t=o("ArticleMeta");return a(),i("div",null,[p[0]||(p[0]=e("h1",{id:"意义危机-如何做一件真正重要的事",tabindex:"-1"},[n("意义危机（如何做一件真正重要的事） "),e("a",{class:"header-anchor",href:"#意义危机-如何做一件真正重要的事","aria-label":'Permalink to "意义危机（如何做一件真正重要的事）"'},"​")],-1)),s(t),p[1]||(p[1]=l('<p><a href="https://www.youtube.com/embed/uy9_bfhfFvQ?si=3477V2T8htM3s5kv" target="_blank" rel="noreferrer">观看原文视频</a></p><p>首先，感谢约翰·维尔维克（John Vervaeke）提出“意义危机”这个概念。我还没有看过他关于这个主题的系列节目，但我听说反响很好。</p><p>这封信是写给那些想要做一件真正重要的事的人的。</p><p>因为如果你足够留心，现代世界的现状并不难看清。</p><p>我们对手机成瘾。我们与自然脱节。我们对公立教育失去了信任，而且是有理由的。人们逐渐意识到，一种源自普鲁士军事国家的教育模式根本行不通。换句话说，这种教育模式本质上是契约奴仆教育的镶像——它被创造出来是为了让人保持弱小、愚昧、无力，即使这不是它的初衷，也是基于地位与生存驱动的激励机制所导致的结果——它必然会让人们对这套体制失去信任，因为你的人生轨迹注定会走向你所憎恶的地方。</p><p>他们最终会走向哪里？走向一份工作，随着年岁增长，被取代的威胁越来越大。如果你看不清这一点，我建议你想清楚超专业化教育会导致什么。你被“地位”蒙蔽了双眼，去追求一个学位。而因为这样做，你大概根本没有在业余时间去追求真正的教育。于是你把心智收窄到单一目标上，让它被一种单向的世界观所塑造，只为成为一种用处：一名打工者。</p><p>而一旦你成为打工者，你开始意识到，你花了这么长时间为之努力的东西（1）极有可能被取代，（2）而且丝毫没有意义。你失去了童年时那份为生活注入活力的好奇心与惊奇感。</p><p>每个人不是在上班，就是在家里害怕上班。人们几乎没有欲望去浸润于现实中的善、真与美，那些能够重新校准你心智、使你走向对这些事物有意义的贡献的东西。</p><p>成瘾。脱节。缺乏信任。缺乏稳定。缺乏教育。害怕被取代。追逐地位。生存模式。一场逐渐滑向混乱的过程，让我们不断质疑自己存在的意义。你不断追问自己为什么要工作这么长时间，你的人生本可以做些更好的事情，这一切制造出一种焦虑与不堪重负的状态，把你困在一种迷雾般的知觉中，让你根本无法真正想清楚脱身之策，更糟的是，你也没有时间或精力去获取那套能让你看清全局、创造解决方案的广泛技能。</p><p>这些就是我们正面临的这场意义危机的种种特征。</p><p>那么，我们该<strong>做</strong>什么？</p><p>我们如何才能活出有意义的人生？</p><p>我们如何在继续前进的同时，重新连接我们已经失去的东西？</p><p>我们要如何以一种不会被飞速进步的人工智能与技术淘汰的方式来教育自己？</p><p>我们要如何找到<strong>属于自己</strong>的独特而个体化的道路，并感觉到自己正在做一件真正重要的事？</p><p>让我们一探究竟。</p><h2 id="意义方程式" tabindex="-1">意义方程式 <a class="header-anchor" href="#意义方程式" aria-label="Permalink to &quot;意义方程式&quot;">​</a></h2><p>如果我们的生活毫无意义，那我们在这里究竟是为了什么？</p><p>我们该拿自己的人生做什么？</p><p>我们该如何理解痛苦与苦难？</p><p>美好人生真的就像信仰上帝那么简单吗？信仰不过是对那个事物的一张脱节的地图，而不是那个事物本身，而这张地图又要经过一个人的文化、价值体系、语言与成长条件的解读。而地图，大多数时候，都与实地相去甚远。</p><p>我有一种感觉，我们都想要感觉自己是有用的。我们渴求目的感。毕竟我们是社会性生物……我们想要感觉自己——就像自然界那样——与某种比我们自身更宏大的东西相连接。而一旦失去这种连接，我们就开始把生活看作毫无意义。</p><p>那么问题来了：我该如何重新连接到那真正重要的东西？我们又该如何判断什么才是真正重要的？</p><p>要重新建立连接，我们需要剥离并重新定向我们最根本的体验。要判断什么才重要，我们需要从多个学科和文化中汲取养分，去揭示一种整体性的方向——或者说一种最高秩序——将自己置身其中，作为对抗混乱与无意义的解药。</p><p>归根结底，存在3种基本的类别，或者说存在模式。</p><ul><li><strong>存在（Being）</strong>——与现实、直接体验、当下时刻的连接。</li><li><strong>行动（Doing）</strong>——对现实与他人体验的贡献。</li><li><strong>成为（Becoming）</strong>——提升你连接现实、进而贡献于现实、个人体验以及他人体验的能力。</li></ul><p>我们每天都在从事这三者。但当我们无意识地这样做时，一个巨大的问题就出现了。我们在成长过程中被赋予了目标和价值观。我们<strong>做</strong>什么、我们<strong>成为</strong>什么，往往取决于别人的心意。学校、工作、社会都在投射他们认为好的东西——往往是出于自利——从而把我们引入一个陷阱，让我们质疑自己是否理智。</p><p>存在、行动与成为构成一个反馈回路。</p><p>它们彼此相互影响。</p><p>你在<strong>存在</strong>上花费的时间越多，你在熟悉的过去或可预测的未来中消耗的心理时间就越少。你沉浸在直接体验之中。你的知觉变得清晰。你能达到一种中性——或者说平静——的心境。你不会把自己投射进一个充满压力的、由各种待办事项堆砌起来的未来，即便你现在并不身处那种情境，也不会因此而感到那种压力。你也不会反复回味一段痛苦的过去，从而导致同样的问题。</p><p>从这种清晰知觉的状态出发，你的<strong>行动</strong>会在意识的程度上不断提升。你开始专注于真正重要的事，并朝着更深远的未来去思考。你的选择随之塑造出你<strong>成为</strong>的样子，而当你是从更高的意识与连接状态出发去做这件事时，你的身份认同就会扩展，摆脱其原有的局限。意义也就变得更容易被理解。</p><p>不幸的是，大多数人忽视了“存在”，却困在了“行动”模式里。他们的注意力锁定在下一个任务、下一个事件、下一个梗图、下一次愉悦、下一个焦虑或压力的来源上，于是他们最终就<strong>成为</strong>了那种性质的东西。牢牢锁定在“下一个”上，回避着“当下”。他们的心智开始收窄，陷入一种无意义的状态，因为他们已经与现实失去了联系。</p><p>这就是我们的起点。</p><p>当下。存在。直接体验。维持连接。</p><p>在我们继续深入之前，考虑为“存在”留出一些时间，即便你没有察觉到它的直接效果。去冥想。找一天深入自然。去散步，试着把你的觉知“推向”天空。凝视你的手10分钟，惊叹于它的精妙复杂。更深入地进入你的感官。洗碗时感受水流过双手的感觉。细细品味你正在吃的食物中那些细微的味道。去探索此时此刻正在发生的人类体验。</p><p><em>多去浸润于美之中。</em></p><p>它无处不在，环绕在你周围。与它同坐，直到你能真正看见它。用心观察，直到看得清晰。</p><p>从这种连接的状态出发，我们要如何确保自己<strong>正在做</strong>那些真正重要的事情？</p><h2 id="与最高秩序对齐" tabindex="-1">与最高秩序对齐 <a class="header-anchor" href="#与最高秩序对齐" aria-label="Permalink to &quot;与最高秩序对齐&quot;">​</a></h2><p>我们并未适应这个混乱的现代环境。</p><p>手机。电脑。信息无处不在。要从噪音中筛选出信号变得越来越难。既然财富与熵是两个对立的极端，那么不确定性越大，创造价值的机会就越多。人们在互联网上学习以前不可能学到的技能、建立以前不可能建立的事业，但许多人却比以往任何时候都更加充满不确定感。他们不知道该如何在这一切混乱之中建立秩序。</p><p>在工业革命之前，我们与小型的社区和部落互动。</p><p><em>你接触到的主要信息，是由那个社区或部落的长者所传承下来的。某种意义上，就是一位导师。</em></p><p>过去，每个人都处在同一个认知框架之下。</p><p>而现在，每个人都处在不同的认知框架下，这就制造出了冲突。我们正处于一场心理战争之中——一场关于世界观与身份认同的战争。</p><p>要理解这一点，让我们从最基础的层面开始梳理。</p><p>我们缺乏意义，是因为我们无法理解眼前的混乱。</p><p>心智渴求秩序，而一旦通过将心智扩展到最高秩序来维持秩序，意义就不难找到了。</p><p>要活出有意义的人生，我们可以从多个领域综合出一些坚实的结论，比如：</p><ul><li>心流心理学</li><li>发展阶段理论</li><li>现实的终极结构</li></ul><p>在这封信的下一部分，我们可以运用这种理解，去开创属于我们自己独特的人生道路——一条通过精通自我与技艺、从而以一种真正对他人有意义的方式做出贡献的道路。</p><p><a href="https://embeds.beehiiv.com/bd10be62-1099-4a34-95b8-16711b1f90f3" target="_blank" rel="noreferrer">观看原文视频</a></p><h3 id="如何进入心流状态" tabindex="-1">如何进入心流状态 <a class="header-anchor" href="#如何进入心流状态" aria-label="Permalink to &quot;如何进入心流状态&quot;">​</a></h3><blockquote><p>它们有规则，要求人们学习技能；它们设定目标；它们提供反馈；它们让掌控成为可能。它们通过让活动尽可能与日常生活中那种所谓的“至上现实”区分开来，来促进专注与投入。——米哈里·契克森米哈赖（Mihaly Csikszentmihalyi）</p></blockquote><p>当人们进入心流状态时，他们称之为一种“灵性体验”。</p><p>然而，我认为这种描述对于实际发生的事情来说是有误导性的。</p><p>大多数“灵性体验”更准确的描述应该是<em>清晰的知觉</em>。清晰的知觉会带来与超越性三元素——善、真、美——相一致的决策。</p><p>没有分心。没有投射。局限极少甚至没有局限。你感觉自己无懈可击，因为你完全锁定在此时此地。你接入了现实的源代码，并与之同流。</p><p>要进入心流状态，或者达到一种极其清晰的知觉状态，你需要具备几个条件。</p><p><strong>1）一套层级化的目标体系</strong></p><p>当心智拥有一条清晰的、可以专注其上的路径时，秩序就产生了。</p><p>而当这条路径上出现知识、技能或理解上的缺口时，混乱就产生了。</p><p>当你在进行一场对话时，如果你们没有共同的目标，这场对话很可能会演变成冲突和争论。你在社交媒体上随处可见这种情况：拥有截然不同世界观的人们在争论自己的观点，却完全没有试图理解对方的心智正朝着什么目标努力。</p><p><em>每个人都在朝着某个目标努力。</em></p><p>对大多数人来说，那些目标是别人分配给他们的。他们照父母、老师和权威人物说的去做，于是学习那一套狭窄的知识、获得那一套狭窄的技能，去做那些狭窄的事情，这就把他们的心智塑造成了一种可能具有破坏性的状态。</p><p><em>跳出局限，去审视你<strong>自己</strong>到底想从人生中得到什么。</em></p><p>建立一个框架。愿景与反愿景。你想要的和不想要的人生。让它随时间演化。一开始它不会是完美的。从那里出发，建立一套层级化的目标体系：十年目标、一年目标、月度、每周和每日的优先事项。</p><p>这些目标是为了方向感与清晰度而存在的。你并不需要精确地实现这些目标本身。如果它们发生变化，那就让它们变化吧。</p><p><strong>2）深层的兴趣</strong></p><p>沉思你的人生。</p><p>你想要什么，不想要什么。</p><p>这些临时性的目标为你的心智搭建出一个框架。</p><p>那么现在，哪种兴趣、话题或技能能帮助你把这幅拼图的其中一块拼实，并推动你朝着理想的生活方式前进？</p><p>从那里开始。选一个东西开始研究。为它划出时间。读一本基础的书。看一场讲座或播客。关注新的社交账号。让你的心智接触更多信息，让你的愿景去过滤出信号。</p><p>这只是起点。正如我们将学到的，通过基于兴趣的教育，你将不得不学习更多、更多的东西。你将不得不终身学习。要精通一个兴趣，它会要求你更深入。它会要求你学习另一个，再学习另一个，直到你对生活本身的种种复杂之处都产生了深深的兴趣。如果你认为<strong>万事万物</strong>——我是说真的万事万物——<strong>不</strong>有趣，那说明你已经失去了立足点。你分心了。</p><p>如果一个良善、真实、美好的生活对你重要，那么任何与之不一致的存在方式或行为方式，按定义来说，就是在<em>浪费你的时间</em>。</p><p><strong>3）挑战与技能</strong></p><p>如果你的技能高，而挑战低，你会感到无聊。</p><p>如果你的技能低，而挑战高，你会感到焦虑。</p><p>这两种情况都会阻碍你进入心流，增加混乱的可能性，如果长期不加以处理，还会导致无意义感。</p><p>无聊源于以自我为中心。你的专注会破裂，一个新的欲望突然冒进脑海，相关的想法开始填满你的注意力。</p><p>如果你在工作中感到无聊，你会开始想着还有哪些更有生产力的事情可以做。</p><p>焦虑源于自我意识。你的注意力转向你对自我的概念，相关的想法又开始渗入你的意识领域。</p><p>如果你承担了自己能力还不够胜任的工作，或者挑战一个比你水平高得多的对手，怀疑的负面想法就会开始涌入。</p><p>对抗混乱的解药，是一个基于兴趣的项目。</p><p>项目会迫使你有效地学习。它们会帮助你意识到，在打造一个项目中获得成功，并不像学一门技能那么简单。在一人企业中，如果你想获得财务自由，你不会只学“营销”。不会的。你可能从那里开始，但接着你会接触到品牌、内容、产品、说服、心理学，以及更多在你看到初步成果之前根本不会显现出来的辅助技能。</p><p>有意义的项目会为你的心智建立秩序，并把你的注意力收窄到你每天都需要拉动的那些杠杆上。</p><p>但这不是故事的结尾。我们会在最后一部分再回到这个话题。</p><p>附注：如果你没有想学的技能，可以考虑写作。你计划学习的任何其他技能或兴趣，都会要求你学会写作。如果你想真正获得报酬并能持续下去，你必须让人们被你的作品吸引。<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">点击这里了解 2 Hour-Writer。</a></p><h3 id="你的心智层次如何塑造你看待世界的方式" tabindex="-1">你的心智层次如何塑造你看待世界的方式 <a class="header-anchor" href="#你的心智层次如何塑造你看待世界的方式" aria-label="Permalink to &quot;你的心智层次如何塑造你看待世界的方式&quot;">​</a></h3><p>要进入心流状态，你需要一个目标层级、深深的兴趣，以及能要求某种技能水平的挑战。</p><p>但我们所有人在人生的不同阶段，处于不同的发展水平。</p><p>我们都是从不同的元目标出发运作的。我们看重的事物、值得为之行动的东西，各不相同。</p><p>为什么这很重要？</p><p>因为，说实话，如果你处于较低的发展阶段，却装作自己处于更高的阶段，那是不合适的。当你还没有赢得那种经验时，戴上一副“灵性”的帽子，那不是灵性。那是在追逐地位。</p><p>两周前我们在<a href="/letters/how-to-join-the-top-1-of-intelligence-full-guide">《如何变得比99%的人更聪明》</a>中详细拆解了自我发展的9个阶段，所以这里我们只笼统地过一遍这些阶段，帮助理解。</p><p>大多数人，在大多数领域中，会经历4个大的阶段：</p><ul><li><strong>以自我为中心</strong>——专注于自身的生存。</li><li><strong>以群体为中心</strong>——专注于自己所属群体、部落、国家或意识形态的生存。</li><li><strong>以世界为中心</strong>——专注于人类和生物圈的生存。</li><li><strong>以宇宙为中心</strong>——专注于宇宙及其以外的生存与和谐，这是最高的秩序。</li></ul><p>作为一个社会，我们大多数人仍处于以群体为中心的阶段。选举就是一个很好的例证。人们仍然更在意维护自己的立场，而不是追求真相、超越那种有害的身份认同。</p><p>这就牵扯出了心智生存这个话题。动物试图在基因层面延续信息，而人类则试图在基因<em>和意识</em>两个层面延续信息。</p><p>这一点可以在所有领域中看到，从宗教到商业，到生态学，到人际关系。</p><p>当你的宗教（以群体为中心的）信念受到挑战时，你可能会感到受威胁，仿佛你的心智之体，或者说身份，无法存续下去，于是你试图通过传教和争辩来复制你脑中的信息，坚持自己那有限的世界观应该被对方所采纳。</p><p>我们可以列举更多例子，但为了简洁起见，你的大部分情绪反应和被冒犯的感受，都源于一种无法打开心智、将身份扩展到下一阶段的无能。</p><p>这跟有意义的人生有什么关系呢？</p><p>好吧，如果你像80%以上的人那样，如此专注于自己和自己所属的群体——而这些概念（宗教、教育、政治等）正随着信息的快速传播和技术的加速而四处爆裂——那么在你尝试自我发展、迈向下一阶段之前，你会有点像迷失在虚空之中。</p><p><strong>趣味小知识：</strong><em>定期冥想能帮助你从某个特定阶段中“脱困”，并加速抵达下一阶段，因为它有助于理解你当前所处的阶段，并厘清朝向下一阶段的种种感知。</em></p><p>在本信的接下来几个部分，我们将学习如何进化到更高的阶段，以及作为个体，你应该做哪些有意义的事情。</p><h3 id="关于进化与终极实相的简要说明" tabindex="-1">关于进化与终极实相的简要说明 <a class="header-anchor" href="#关于进化与终极实相的简要说明" aria-label="Permalink to &quot;关于进化与终极实相的简要说明&quot;">​</a></h3><p>两个词：</p><p><em>超越且包含。</em></p><p>好吧，我说谎了。再加一个词：</p><p><em>全子（Holons）。</em></p><p>Dan，你到底在说什么鬼？</p><p><em>全子（holon）</em>是一个概念，帮助描述实相的结构和本质。宇宙的构成单元。这个词最早由亚瑟·库斯勒（Arthur Koestler）提出，现在被肯·威尔伯（Ken Wilber）所采用，一个全子是一个“整体/部分”。既是自身的一个整体，<em>同时</em>也是别的什么东西的一部分。</p><p>对于那些研究过系统思维，或者研究过古希腊的“宇宙论”哲学——一个有序而和谐排列的系统，就像宇宙那样，其中万物皆有目的——的人来说，你会明白这将走向何方。</p><p><em>万事万物都超越并包含它之前存在的东西。</em></p><p>原子到分子，到细胞，到有机体。字母到词语，到句子，到段落。自我到群体，到世界，到宇宙。员工到团队，到部门，到公司。所有这些都以无限的方式相互连接，就像员工本身既是一个整体，同时又是一个家庭或一个群聊的一部分，又比如一整杯咖啡里的蜂蜜，这两者都要经过养蜂人和咖啡制造商的加工处理，而这些人在各自的整体流程中可能造成、也可能没有造成伤害。实相是由种种隐喻性的全子构建而成的。隐喻孕育理解。</p><p><strong>小贴士：</strong>整体性思维，即以全子的方式思考，其实相当有趣，能带来更深入的对话和解决方案。</p><p>一个关键的洞见是：实相是层级性的。然而，并非所有的层级都是一样的。存在支配型层级和自然/生长型层级。支配型层级，或者说<em>强加的秩序</em>，往往是压迫性的、有害的。可以理解左派为什么想要清除这类层级，但他们常常把两种层级混为一谈，导致他们想要拆解世界上一切秩序，无论好坏，结果造成大规模的混乱（这也是我们陷入这种无意义处境的一个重大原因）。自然层级则是<em>涌现的秩序</em>。在经历冲突、痛苦或问题解决之后，一个解决方案，或者说层级中的某一层，会涌现出来，超越并包含其余的一切，从而带来越来越大的整全与包容。</p><p>所以，通过让<em>你所做的事</em>与宇宙（Kosmos）这最高秩序对齐——它的系统性特质可以映射到上帝、梵（Brahman），或任何其他全知、全在、全能的实相之<em>身份</em>（而非实相本身）——你会开始把实相看作一个相互连接的整体，你在其中的位置或使命也会逐渐显现出来。你会感知到，你的存在、行为与成长，会向所有人、所有事物送出一道波纹，你的每一个决定都承载着巨大的责任分量，它会压垮弱者，也会赋能强者。</p><p>由于这一点已经在跨文化的层面被绘制和研究过，但还没有被充分综合，或在足够大的规模上被理解到可以视为常态的程度（这正是我写作的目的所在），所以最明智的做法是，通过解决问题、习得技能、贡献他人，把自己导向超越个人自私需求的身份扩展方向。</p><p>这就把我们带向了我们最重要的一课：</p><h2 id="那么-我的人生该做什么" tabindex="-1">那么，我的人生该做什么？ <a class="header-anchor" href="#那么-我的人生该做什么" aria-label="Permalink to &quot;那么，我的人生该做什么？&quot;">​</a></h2><blockquote><p>幸福就是那种力量在增长的感觉——是阻力正在被克服的感觉。——弗里德里希·尼采（Friedrich Nietzsche）</p></blockquote><p>对尼采来说，幸福是一种对自身周遭环境掌控的感觉。一种进步正在发生的感觉。</p><p>对于米哈里·契克森米哈伊（Mihaly Csikszentmihalyi），也就是心流心理学之父来说，这正是<em>愉悦感</em>的来源，我觉得“愉悦感”比“幸福”这个词更贴切。</p><p>但这就引出了一个问题：我该朝着什么方向取得进步，才能带来最大程度的愉悦感？</p><p>我怎么才能找到<em>重要的事、我擅长的事，以及被需要的事</em>这三者之间那个完美的交汇点？</p><p>我该学什么？我该怎么学？我该如何以一种有意义的方式为人类做出贡献，同时还能因此获得丰厚的回报？</p><p>以下是几个步骤。</p><h3 id="_1-你自己的道路" tabindex="-1">1）你自己的道路 <a class="header-anchor" href="#_1-你自己的道路" aria-label="Permalink to &quot;1）你自己的道路&quot;">​</a></h3><p>我们必须做的第一件事，就是反抗那条无意义的道路。</p><p>我们必须从零开始。我们必须拒绝那种唯一目的就是培养“有用”工人的教育体系——这种工人依赖别人来发薪水。作为交换，他们放弃了对自己情绪的掌控（因为支付账单带来的压力），这反过来影响了他们的潜力（他们的心智始终狭窄），也阻止了他们做出改变（如果他们把自己陷得太深）。</p><p>我们该如何从零开始？</p><p>通过构思、创造、迭代出我们自己的叙事。我们<em>自己</em>的故事。而不是父母、老师和同龄人赋予你的那个叙事。</p><p>要做到这一点，你要创造一个愿景和一个反愿景。这会开始形成一个心智框架，让你能把注意力集中在真正重要的事情上。既然我们已经讨论过这一点，这里再给出几个关键问题，帮你挖掘出你到底想做什么：</p><ol><li>你最受困扰的是什么？可以是某种行为、世界的现状、人们的思维方式等等。</li><li>你小时候最感兴趣的是什么？</li><li>如果你能改变世界的一个部分，会是什么？你是否意识到它带来的影响？</li><li>谁最能给你带来启发？你能延续他们的工作吗？</li><li>如果你能整天研究一件事情，那会是什么？</li></ol><p>我还能问出上千个问题，但我会让这5个问题去激发你更多的思考。花至少10分钟，静静地和它们坐在一起。准备一本笔记本会很有帮助。</p><p>你所需要的，只是一个起点。</p><p>一点好奇的火花，去开启你迈入未知的旅程。</p><p><em>你个人独特的道路,是连接你的反愿景与愿景之间的桥梁。获取知识、构建解决问题的方案、发展自己以应对更复杂的挑战。在这条路上,你可以用自己搭建的这座桥,去帮助他人。</em></p><h3 id="_2-基于兴趣的教育" tabindex="-1">2)基于兴趣的教育 <a class="header-anchor" href="#_2-基于兴趣的教育" aria-label="Permalink to &quot;2)基于兴趣的教育&quot;">​</a></h3><p>关键点在这里:</p><p>没有所谓正确的道路。</p><p>如果我能给你指定一条道路,你最终会落到和别人一样的地方——可替代且依赖他人。你必须通过一种更好的教育方式,创造出属于自己的道路。那就是自我教育。</p><p>我高中时是全A优等生。</p><p>在我上大学之前,我父母离婚了,家里钱变得很紧张,我很快意识到我不想落入那种境地。小时候,我就很善于观察是什么让我父母的生活看起来不快乐、不健康、不充实。</p><p>仅这一点,就点燃了我基于兴趣的教育之火。我开始质疑一切,而多亏了互联网,那些问题能得到部分解答。剩下的答案则随着我经验的增加而逐渐找到。</p><p>我从研究宗教开始,然后研究反对宗教的各种论点。当我找不到令自己满意的答案时,我开始押注于自己。我投身健身与营养领域,但意识到那只是我生活中的一个方面。我知道我必须理清自己的财务状况,于是开始学习商业。这一切感觉都很浅薄,于是我挖得更深,投入了哲学的研究。</p><p>过去十年里,我尝试了大量的营养模型、训练方案、商业模式、宗教世界观、形而上学哲学等等,这让我比任何狭隘的专业教育都更具适应性。</p><p>我意识到,为了在商业上做到优秀,我必须提升到更高的一层——心智哲学、元系统等能让你成长到更高发展阶段的东西。</p><p><strong>现在跟我走一步,精彩的部分来了:</strong></p><p>历史上大多数最伟大的思想家,比如马可·奥勒留(Marcus Aurelius),都有幸师从世界上最好的老师。为了让他们准备好担当领导角色,他们由顶尖的数学家和战略家亲自指导。他们伟大并非纯粹靠运气。</p><p>工业革命之后,这种情况消失了。每个人都开始在公立学校体系中,向那些缺乏成为最优秀者动机的老师学习。</p><p>如今,随着互联网和社交媒体的兴起,<em>你</em>也能接触到世界上最伟大的头脑。他们每天都在发布内容,因为那正是他们的<em>使命所在</em>。</p><p>然而,他们分发的信息仍然是为了迎合一个肤浅的算法而量身定制的。你可以从中获取某个领域的通用信息,但那不会让你成为最优秀的人。</p><p>所以,我的建议是这样的:</p><ul><li>当你感受到那种好奇的火花时,全力投入。</li><li>关注新的人。买书。散步或通勤时听播客。刷YouTube讲座刷到饱。</li><li>当你发现一个重要的主题时,为它购买一门课程。</li><li>当你发现自己想深入学习某一件事时,去寻找一位导师。</li></ul><p>我们不生活在古希腊,你也不是王位的继承人。你没有那种默认就能获得一位伟大老师的特权。</p><p>所以,你将不得不为他们的时间付费。而这只有对那些(1)不理解金钱本质,或(2)与金钱有着非理性且糟糕关系的人来说才是坏事。如果你是这样的人,读一读我的信,<a href="/letters/the-truth-about-money-and-how-to-make-a-ton-of-it">《关于金钱的真相》</a>。</p><p>没错,现代的导师们不应该免费赠送他们的知识。智慧的双唇是紧闭的,除非面对理解的耳朵。</p><h3 id="_3-对人类的贡献" tabindex="-1">3)对人类的贡献 <a class="header-anchor" href="#_3-对人类的贡献" aria-label="Permalink to &quot;3)对人类的贡献&quot;">​</a></h3><p>这整封信的目的,是帮助你找到意义。</p><p>到目前为止,我们已经了解到:</p><ul><li>有意义的生活是一种存在、行动与成为之间的递归关系,用以欣赏、贡献,并深化你欣赏与贡献的能力。行动必须源自存在本身。</li><li>你是被称为社会、文化等这一进化的意识形态的一部分,而你的责任,就是通过贡献来维系并强化这种连接。</li><li>贡献的最佳方式,是找到&quot;什么重要&quot;、&quot;我擅长什么&quot;以及&quot;什么是被需要的&quot;三者的交集。</li></ul><p>在我看来,学习和贡献的最佳场所就是互联网。那里正是当下注意力所在之处,而如果你想以任何有意义的方式做出贡献,你就需要注意力。</p><p>那些不被困在人气或地位竞赛中的个人品牌与创作者,拥抱了不确定性的道路,并在他们销售的独特且有帮助的产品中找到了意义。事实上,他们根本不是什么个人品牌或内容创作者。他们只是一群看到了机会的人——将自己所拥有的价值分发出去,并借此获得报酬——就在当下注意力所在的地方。也就是<em>他们能够带来最大改变的地方。</em></p><p>如果你想维持自己所热爱的事情,那你就必须赚钱。</p><p>如果你想通过做自己热爱的事情来赚钱,那你就必须创办一家企业。</p><p>如果你想创办一家企业,你就必须用做这件事所需的广泛技能来教育自己。这<em>正是</em>你基于兴趣教育的一部分。在某个时刻,如果你想继续你的精进之路,你就会对商业产生兴趣。希望你能经历那些发展阶段,以一种能造成最小伤害的方式去做这件事(不,企业并不邪恶,但如果不去创办企业,只会确保那些邪恶的企业占据主导地位)。</p><p>这篇已经写得很长了,而且我之前也写过相关内容,所以就在这里收尾吧。</p><p>我以这句话作为结尾:</p><p>如果你想更多地了解新媒体与新经济,去看看我在YouTube上的一人企业播放列表。</p><p>如果你想围绕自己的兴趣创办一份有意义的事业,可以看看<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2-Hour Writer</a>(用于建立受众)和<a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">Mental Monetization</a>(用于将你的知识转化为产品,分发给那些受众)。</p><p>——丹(Dan)</p><hr><p><a href="/en/letters/the-meaning-crisis-how-to-do-something-that-matters">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',177))])}const k=r(h,[["render",m]]);export{_ as __pageData,k as default};
